use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let mut prefix = String::new();
    let mut chars = input.as_array().unwrap();
    while let Some(&item) = chars.next() {
        if let Some(&s) = item.as_str() {
            if prefix.is_empty() || s < prefix {
                prefix = s.to_string();
            }
        } else {
            break;
        }
    }
    Value::String(prefix)
}
